def apply(callable, *args):
    return callable(*args)

def identity(x):
    return x

def thread_first(data, *fns):
    result = data
    for fn in fns:
        result = fn(result)
    return result

def compose_left(f, g):
    def composed(x):
        return f(g(x))
    return composed

def compose(*fns):
    def composed(x):
        for fn in reversed(fns):
            x = fn(x)
        return x
    return composed

def pipe(*fns):
    def p(x):
        for fn in fns:
            x = fn(x)
        return x
    return p

def peekn(n, data):
    if n > 0:
        return data[:n]
    else:
        return []

def peek(data):
    return peekn(1, data)

def fold(iterable, initial, fn):
    result = initial
    for item in iterable:
        result = fn(result, item)
    return result

def merge(*maps):
    result = {}
    for m in maps:
        result.update(m)
    return result

def merge_with(*maps):
    result = {}
    for m in maps:
        result.update(m)
    return result

