class Compose:
    def __init__(self, *fns):
        self.fns = fns

    def __call__(self, x):
        for fn in reversed(self.fns):
            x = fn(x)
        return x

def curry(fn, *a):
    def curried(*b):
        return fn(*a, *b)
    return curried

def excepts(*exc_types):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except exc_types:
                pass
        return wrapper
    return decorator
